import { getFungibleTokens, getSolution, getContractSolution, getSupportedChains, getUserFungibleTokens, getUserNativeTokens, setBaseUrl, BASE_URL, getContractCallSolution, } from "./api";
export * as api from "./api";
export * from "./enums";
class Sprinter {
    // in memory "cache"
    #tokens;
    #chains;
    #requests = {};
    #fetchOptions;
    constructor(fetchOptions = {}) {
        this.#fetchOptions = fetchOptions;
    }
    async getAvailableTokens(options = {}) {
        if (!this.#tokens)
            this.#tokens = await this.deferredRequest("tokens", () => getFungibleTokens(this.makeFetchOptions(options)));
        return this.#tokens;
    }
    async getAvailableChains(options = {}) {
        if (!this.#chains)
            this.#chains = await this.deferredRequest("chains", () => getSupportedChains(this.makeFetchOptions(options)));
        return this.#chains;
    }
    async getUserBalances(account, tokens, options = {}) {
        const tokenList = tokens || (await this.getAvailableTokens(options));
        const [balances, nativeTokens] = await this.deferredRequest(`balances-${account}`, () => Promise.all([
            Promise.all(tokenList.map((token) => getUserFungibleTokens(account, token.symbol, options).then((balances) => ({
                symbol: token.symbol,
                balances,
            })))),
            getUserNativeTokens(account, options),
        ]));
        return balances.reduce((previousValue, { symbol, balances }) => {
            previousValue[symbol] = {
                total: balances
                    .reduce((prev, cur) => prev + BigInt(cur.balance), 0n)
                    .toString(),
                balances,
            };
            return previousValue;
        }, {
            ["ETH"]: {
                total: nativeTokens
                    .reduce((prev, cur) => prev + BigInt(cur.balance), 0n)
                    .toString(),
                balances: nativeTokens,
            },
        });
    }
    async getSolution(settings, options) {
        if (typeof settings !== "object" || settings === null)
            throw new Error("Missing settings object");
        if ("contractCall" in settings)
            return await getContractSolution(settings, this.makeFetchOptions(options || {}));
        return await getSolution(settings, this.makeFetchOptions(options || {}));
    }
    async getCallSolution(settings, options) {
        if (typeof settings !== "object" || settings === null)
            throw new Error("Missing settings object");
        return await getContractCallSolution(settings, this.makeFetchOptions(options || {}));
    }
    deferredRequest(name, request) {
        if (!(name in this.#requests)) {
            this.#requests[name] = request();
            void this.#requests[name].finally(() => {
                void setTimeout(() => {
                    delete this.#requests[name];
                }, 1000);
            });
        }
        return this.#requests[name];
    }
    makeFetchOptions(options) {
        return { ...this.#fetchOptions, ...options };
    }
}
export { Sprinter, setBaseUrl, BASE_URL };
